// ------------------------------ Types ------------------------------

/** Base props shared by all plot tooltip content components. */
export interface PlotTooltipBaseProps {
	/** The X,Y coordinates of the plot */
	plotCoord: float2;
	/** Whether to show debug information */
	showDebug?: boolean;
	/** The city that owns this plot, or null if unowned. */
	owningCity: City | null;
}

/** Information about a constructible on a plot */
export interface PlotTooltipConstructibleInfo {
	location: float2;
	type: string;
	age: number;
	isAgeless: boolean;
	isBuilding: boolean;
	isWonder: boolean;
	isImprovement: boolean;
	uniqueQuarterType: UniqueQuarterType;
	damaged: boolean;
	complete: boolean;
	overbuildable: boolean;
	title: string;
	description?: string;
	icon: string;
	sortOrder: number;
}

/** Visible plot effect information for tooltip rendering. */
export interface PlotTooltipEffectInfo {
	name: string;
	plotEffectType: string;
	effectType: PlotEffectType;
	eventClass?: string;
	/** Localization key for the source `RandomEvent.Name`, when this effect was created by one. */
	eventName?: string;
	duration: number;
	onlyVisibleToOwner: boolean;
	owner: PlayerId;
}

// ------------------------------ Helper Functions ------------------------------

/** Get current age's chronology index */
export function getCurrentAge(): number {
	return GameInfo.Ages.lookup(Game.age)?.ChronologyIndex ?? 0;
}

/** Get set of ageless type identifiers */
export function getAgelessTypes(): Set<string> {
	return new Set(GameInfo.TypeTags.filter((e) => e.Tag == "AGELESS").map((e) => e.Type));
}

/**
 * Get the terrain label for a plot location.
 * @param location The X,Y plot location
 * @param showDebug Whether to include debug type info
 */
export function getTerrainLabel(location: float2, showDebug: boolean): string {
	const terrainType = GameplayMap.getTerrainType(location.x, location.y);
	const terrain = GameInfo.Terrains.lookup(terrainType);
	if (terrain) {
		if (showDebug) {
			if (terrain.TerrainType == "TERRAIN_COAST" && GameplayMap.isLake(location.x, location.y)) {
				return Locale.compose("{1_Name} ({2_Value})", "LOC_TERRAIN_LAKE_NAME", terrainType.toString());
			}
			return Locale.compose("{1_Name} ({2_Value})", terrain.Name, terrainType.toString());
		} else {
			if (terrain.TerrainType == "TERRAIN_COAST" && GameplayMap.isLake(location.x, location.y)) {
				return "LOC_TERRAIN_LAKE_NAME";
			}
			return terrain.Name;
		}
	}
	return "";
}

/**
 * Get the biome label for a plot location.
 * @param location The X,Y plot location
 * @param showDebug Whether to include debug type info
 */
export function getBiomeLabel(location: float2, showDebug: boolean): string {
	const biomeType: BiomeType = GameplayMap.getBiomeType(location.x, location.y);
	const biome = GameInfo.Biomes.lookup(biomeType);

	if (biome && biome.BiomeType != "BIOME_MARINE") {
		if (showDebug) {
			return Locale.compose("{1_Name} ({2_Value})", biome.Name, biomeType.toString());
		} else {
			return biome.Name;
		}
	}
	return "";
}

export interface VolcanoFeatureInfo {
	/** The proper name of the volcano (e.g. "Hunga Tonga - Hunga Ha'apai"), or empty if unnamed. */
	name: string;
	/** Whether the volcano is currently active. */
	active: boolean;

	eruptionInfo?: VolcanoEruptionInfo;
}
export interface FeatureInfo {
	type: FeatureType;
	label: string;
	tooltip: string;
	isNaturalWonder: boolean;
	volcano?: VolcanoFeatureInfo;
}
/**
 * Get the feature label and tooltip for a plot location.
 * @param location The X,Y plot location
 * @param plotIndex The plot index for the location
 */
export function getFeatureInfo(location: float2, plotIndex: number): FeatureInfo {
	let label = "";
	let tooltip = "";
	const type = GameplayMap.getFeatureType(location.x, location.y);
	const feature = GameInfo.Features.lookup(type);
	const isNaturalWonder = GameplayMap.isNaturalWonder(location.x, location.y);
	if (feature) {
		label = feature.Name;
		if (feature.Tooltip) {
			tooltip = feature.Tooltip;
		}
	}

	let volcano: VolcanoFeatureInfo | undefined = undefined;
	if (GameplayMap.isVolcano(location.x, location.y)) {
		const active = GameplayMap.isVolcanoActive(location.x, location.y);
		const volcanoName = GameplayMap.getVolcanoName(location.x, location.y);
		const eruptionInfo = MapFeatures.getVolcanoEruptionInfoAt(plotIndex) ?? undefined;
		volcano = { name: volcanoName, active, eruptionInfo };
	}

	return { type, label, tooltip, isNaturalWonder, volcano };
}

/**
 * Get the continent name for a plot location.
 * @param location The X,Y plot location
 */
export function getContinentName(location: float2): string {
	const continentType = GameplayMap.getContinentType(location.x, location.y);
	const continent = GameInfo.Continents.lookup(continentType);
	if (continent && continent.Description) {
		return continent.Description;
	}
	return "";
}

/**
 * Get the river label for a plot location.
 * @param location The X,Y plot location
 */
export function getRiverLabel(location: float2): string {
	const riverType: RiverTypes = GameplayMap.getRiverType(location.x, location.y);
	if (riverType != RiverTypes.NO_RIVER) {
		let riverNameLabel: string = GameplayMap.getRiverName(location.x, location.y);
		if (!riverNameLabel) {
			switch (riverType) {
				case RiverTypes.RIVER_MINOR:
					riverNameLabel = "LOC_MINOR_RIVER_NAME";
					break;
				case RiverTypes.RIVER_NAVIGABLE:
					riverNameLabel = "LOC_NAVIGABLE_RIVER_NAME";
					break;
			}
		}
		return riverNameLabel;
	}
	return "";
}

export interface RouteData {
	name: string;
	type: string;
}
/**
 * Get the route data for a plot location.
 * @param location The X,Y plot location
 */
export function getRouteData(location: float2): RouteData | null {
	const routeTypeHash = GameplayMap.getRouteType(location.x, location.y);
	const route = GameInfo.Routes.lookup(routeTypeHash);
	const isFerry = GameplayMap.isFerry(location.x, location.y);
	let returnString = "";
	if (route) {
		if (isFerry) {
			returnString = Locale.compose(
				"{1_RouteName} {LOC_PLOT_DIVIDER_DOT} {2_Ferry}",
				route.Name,
				"LOC_NAVIGABLE_RIVER_FERRY",
			);
		} else {
			returnString = route.Name;
		}
		return { name: returnString, type: route.RouteType };
	}
	return null;
}

/**
 * Get the resource at a plot location.
 * @param location The X,Y plot location
 */
export function getResource(location: float2): ResourceDefinition | null {
	const resourceType = GameplayMap.getResourceType(location.x, location.y);
	return GameInfo.Resources.lookup(resourceType);
}

/**
 * Get the owning settlement/city name for a plot location.
 * @param location The X,Y plot location
 */
export function getSettlementName(owningCity: City | null) {
	return owningCity?.name;
}

/**
 * Get specialist description for a plot.
 * @param location The X,Y plot location
 */
export function getSpecialistDescription(
	location: float2,
	owningCity: City | null,
): { key: string; args: LocalizedTextArgument[] } | null {
	if (owningCity?.Workers) {
		const maxSpecialists = owningCity.Workers.getCityWorkerCap();
		if (maxSpecialists > 0) {
			const workerInfo = owningCity.Workers.GetTilePlacementInfo(
				GameplayMap.getIndexFromXY(location.x, location.y),
			);
			if (workerInfo.NumWorkers > 0 || !workerInfo.IsBlocked) {
				return {
					key: "LOC_PLOT_TOOLTIP_SPECIALISTS_ASSIGNED",
					args: [workerInfo.NumWorkers, workerInfo.MaxWorkers],
				};
			}
		}
	}
	return null;
}

/**
 * Get constructible info for a plot.
 * @param constructible The constructible component ID
 * @param plotCoordinate The plot coordinate
 * @param currentAge Current age chronology index
 * @param agelessTypes Set of ageless type identifiers
 */
export function getConstructibleInfo(
	constructible: ComponentID,
	plotCoordinate: float2,
	currentAge: number,
	agelessTypes: Set<string>,
	overbuildableConstructibleTypes: ConstructibleType[],
): PlotTooltipConstructibleInfo | null {
	const instance = Constructibles.getByComponentID(constructible);
	const info = instance ? GameInfo.Constructibles.lookup(instance.type) : null;
	const location = instance?.location;

	if (instance && info && location && location.x == plotCoordinate.x && location.y == plotCoordinate.y) {
		const type = info.ConstructibleType;
		const age = GameInfo.Ages.lookup(info.Age ?? 0)?.ChronologyIndex ?? 0;
		const isAgeless = agelessTypes.has(type);
		const isBuilding = info.ConstructibleClass == "BUILDING";
		const isWonder = info.ConstructibleClass == "WONDER";
		const isImprovement = info.ConstructibleClass == "IMPROVEMENT";
		const uniqueQuarterType = instance.uniqueQuarterType;

		if (isBuilding || isWonder || isImprovement) {
			return {
				location,
				type,
				age,
				isAgeless,
				isBuilding,
				isWonder,
				isImprovement,
				uniqueQuarterType,
				damaged: instance.damaged,
				complete: instance.complete,
				overbuildable: overbuildableConstructibleTypes.includes(info.$hash) && isBuilding,
				title: info.Name,
				description: info.Description,
				icon: UI.getIconCSS(info.ConstructibleType),
				sortOrder: isBuilding || isWonder ? (currentAge == age ? 1 : 0) : 2,
			};
		}
	}

	return null;
}

interface PlotYield {
	yieldType: string;
	amount: number;
	name: string;
}

/**
 * Get yield data for a plot.
 * @param location The X,Y plot location
 * @param playerID The player ID
 */
export function getPlotYields(location: float2, playerID: PlayerId): PlotYield[] {
	const plotIndex = GameplayMap.getIndexFromLocation(location);
	const rawYields = GameplayMap.getYields(plotIndex, playerID);
	const yields: PlotYield[] = [];
	if (rawYields) {
		for (const [yieldType, yieldAmount] of rawYields) {
			if (yieldAmount > 0) {
				const yieldDef = GameInfo.Yields.lookup(yieldType);
				if (yieldDef) {
					yields.push({
						yieldType: yieldDef.YieldType,
						amount: yieldAmount,
						name: yieldDef.Name,
					});
				}
			}
		}
	}
	return yields;
}

/**
 * Get district health information for a plot.
 * @param location The X,Y plot location
 */
export function getDistrictHealthInfo(location: float2): {
	currentHealth: number;
	maxHealth: number;
	isUnderSiege: boolean;
	canShow: boolean;
} | null {
	const playerID: PlayerId = GameplayMap.getOwner(location.x, location.y);
	const playerDistricts: PlayerDistricts | null = Players.Districts.get(playerID);

	if (!playerDistricts) {
		return null;
	}

	const currentHealth = playerDistricts.getDistrictHealth(location);
	const maxHealth = playerDistricts.getDistrictMaxHealth(location);
	const isUnderSiege: boolean = playerDistricts.getDistrictIsBesieged(location);

	if (!DistrictHealthManager.canShowDistrictHealth(currentHealth, maxHealth)) {
		return null;
	}

	const revealedState: RevealedStates = GameplayMap.getRevealedState(
		GameContext.localPlayerID,
		location.x,
		location.y,
	);

	if (revealedState != RevealedStates.VISIBLE) {
		return null;
	}

	return { currentHealth, maxHealth, isUnderSiege, canShow: true };
}

export interface PlotOwnerInfo {
	isIndependent: boolean;
	civName: string;
	playerName: string;
	relationship?: string;
	cityStateBonus?: string;
	conquerorInfo?: { isIndependent: boolean; name: string };
	/** The suzerain's player ID when the plot is owned by a city-state that has a suzerain. Used to show the suzerain's leader portrait. */
	suzerainId?: PlayerId;
}

/**
 * Get player ownership info for a plot.
 * @param location The X,Y plot location
 * @param playerID The owner player ID
 */
export function getOwnerInfo(location: float2, playerID: PlayerId | null): PlotOwnerInfo | null {
	if (playerID === null || playerID == PlayerIds.NO_PLAYER) {
		return null;
	}

	const filteredConstructibles = MapConstructibles.getHiddenFilteredConstructibles(location.x, location.y);
	const constructibles = MapConstructibles.getConstructibles(location.x, location.y);
	const player = Players.get(playerID);
	if (!player || !Players.isAlive(playerID)) {
		return null;
	}

	if (filteredConstructibles.length == 0 && filteredConstructibles.length != constructibles.length) {
		return null;
	}

	const civName = GameplayMap.getOwnerName(location.x, location.y);
	const localPlayerID = GameContext.localPlayerID;
	const playerName = player.name;

	if (player.isIndependent) {
		const relationship = GameplayMap.getOwnerHostility(location.x, location.y, localPlayerID);
		const bonusType: CityStateBonusType = Game.CityStates.getBonusType(playerID);
		const bonusDefinition: CityStateBonusDefinition | undefined = GameInfo.CityStateBonuses.find(
			(t) => t.$hash == bonusType,
		);

		return {
			isIndependent: true,
			civName,
			playerName,
			relationship: relationship ?? undefined,
			cityStateBonus: bonusDefinition?.Name,
		};
	} else {
		const districtId: ComponentID | null = MapCities.getDistrict(location.x, location.y);
		let conquerorInfo: { isIndependent: boolean; name: string } | undefined;

		if (districtId) {
			const district: District | null = Districts.get(districtId);
			if (district && ComponentID.isValid(districtId) && district.owner != district.controllingPlayer) {
				const conqueror: PlayerLibrary | null = Players.get(district.controllingPlayer);
				if (conqueror) {
					conquerorInfo = {
						isIndependent: conqueror.isIndependent,
						name: conqueror.isIndependent
							? "LOC_PLOT_TOOLTIP_INDEPENDENT_CONQUEROR"
							: conqueror.civilizationFullName,
					};
				}
			}
		}

		let suzerainId: PlayerId | undefined;
		if (player.isMinor && player.Influence?.hasSuzerain) {
			suzerainId = player.Influence.getSuzerain();
		}

		return {
			isIndependent: false,
			civName,
			playerName,
			conquerorInfo,
			suzerainId,
		};
	}
}

/**
 * The relationship between a unit's owner and the local player.
 * If the owner is a minor or independent, this will include the relationship with their suzerain or independent status.
 */
export interface UnitOwnerRelationship {
	name: string;
	hostile: boolean;
}

function getPlayerRelationship(lpd: PlayerDiplomacy, targetPlayerID: PlayerId): UnitOwnerRelationship | undefined {
	const relationship = lpd.getRelationshipEnum(targetPlayerID);
	if (relationship === DiplomacyPlayerRelationships.PLAYER_RELATIONSHIP_NEUTRAL) {
		return undefined;
	}

	return {
		name: lpd.getRelationshipLevelName(targetPlayerID) ?? "LOC_RELATIONSHIP_UNKNOWN",
		hostile: relationship === DiplomacyPlayerRelationships.PLAYER_RELATIONSHIP_HOSTILE,
	};
}

function getIndependentRelationship(
	independentID: PlayerId,
	localPlayerID: PlayerId,
): UnitOwnerRelationship | undefined {
	const relationship = Game.IndependentPowers.getIndependentRelationship(independentID, localPlayerID);
	if (relationship === IndependentRelationship.NEUTRAL) {
		return undefined;
	}

	return {
		name: Game.IndependentPowers.getIndependentHostility(independentID, localPlayerID),
		hostile: relationship === IndependentRelationship.HOSTILE,
	};
}

export interface UnitInfoSectionProps {
	unit: Unit;
	unitIcon?: string;
	ownerName: string;
	civName: string;
	civSymbol?: string;

	relationship?: UnitOwnerRelationship;

	isMinorOrIndependent: boolean;
	isCivilian: boolean;
	isAtWarWithOwner: boolean;

	treasureFleet?: { originCityName: string; points: number };
}

/**
 * Build tooltip display info for a single unit.
 * @param unit The unit to build info for
 * @param localPlayerID The local observer player ID
 */
function buildUnitInfoProps(unit: Unit, localPlayer: PlayerLibrary): UnitInfoSectionProps | null {
	const owningPlayer: PlayerLibrary | null = Players.get(unit.owner);
	if (!owningPlayer) {
		return null;
	}

	const unitDefinition = GameInfo.Units.lookup(unit.type);
	const unitIcon = unitDefinition ? UI.getIconCSS(unitDefinition.UnitType) : undefined;
	const isCivilian = unitDefinition?.FormationClass === "FORMATION_CLASS_CIVILIAN";
	const civSymbol = Icon.getCivSymbolCSSFromCivilizationType(owningPlayer.civilizationType) || undefined;

	let treasureFleet: { originCityName: string; points: number } | undefined;
	const disbandCityId = unit.getAssociatedDisbandCityId();
	const originCity = disbandCityId != null ? Cities.get(disbandCityId) : null;
	if (originCity) {
		treasureFleet = {
			originCityName: originCity.name,
			points: unit.getDisbandVictoryPoints(),
		};
	}

	const lpd = localPlayer.Diplomacy!;
	const isAtWarWithOwner = lpd.isAtWarWith(owningPlayer.id);
	let relationship: UnitOwnerRelationship | undefined;

	if (owningPlayer.isMinor || owningPlayer.isIndependent) {
		const independentID: PlayerId = Game.IndependentPowers.getIndependentPlayerIDFromUnit(unit.id);
		if (independentID != PlayerIds.NO_PLAYER) {
			const indy = Players.get(independentID);
			if (indy) {
				// If the camp is a city-state, get the relationship of their suzerain
				let civName = indy.civilizationFullName;
				if (owningPlayer.isMinor) {
					const cityStatePlayer = Players.get(independentID);
					const suzerainPlayer = cityStatePlayer?.Influence
						? Players.get(cityStatePlayer.Influence.getSuzerain())
						: null;

					if (suzerainPlayer) {
						relationship = getPlayerRelationship(lpd, suzerainPlayer.id);
					} else {
						relationship = getIndependentRelationship(independentID, localPlayer.id);
						civName = `LOC_CIVILIZATION_INDEPENDENT:${civName}`;
					}
				} else {
					// Wrap with independent singular for non-city-state independents
					civName = `LOC_CIVILIZATION_INDEPENDENT_SINGULAR:${civName}`;
				}

				if (isAtWarWithOwner) {
					relationship = getIndependentRelationship(independentID, localPlayer.id);
				}

				return {
					unit,
					unitIcon,
					ownerName: "",
					civName,
					civSymbol,
					relationship,
					isMinorOrIndependent: true,
					isCivilian,
					treasureFleet,
					isAtWarWithOwner,
				};
			}
		}
		return null;
	} else {
		if (owningPlayer.id !== localPlayer.id) {
			relationship = getPlayerRelationship(lpd, owningPlayer.id);
		}
		return {
			unit,
			unitIcon,
			ownerName: owningPlayer.name,
			civName: owningPlayer.civilizationFullName,
			civSymbol,
			relationship,
			isMinorOrIndependent: false,
			isCivilian,
			treasureFleet,
			isAtWarWithOwner,
		};
	}
}

/**
 * Get unit info for display in the tooltip.
 * @param location The X,Y plot location
 */
export function getUnitEntries(location: float2, localPlayer: PlayerLibrary): UnitInfoSectionProps[] {
	if (GameplayMap.getRevealedState(localPlayer.id, location.x, location.y) != RevealedStates.VISIBLE) {
		return [];
	}
	const plotUnits: ComponentID[] = MapUnits.getUnits(location.x, location.y);
	const results: UnitInfoSectionProps[] = [];
	for (const unitId of plotUnits) {
		const unit = Units.get(unitId);
		if (unit && Visibility.isVisible(localPlayer.id, unit.id)) {
			const info = buildUnitInfoProps(unit, localPlayer);
			if (info) {
				results.push(info);
			}
		}
	}
	return results;
}

/**
 * Get plot effects for a plot.
 * @param plotIndex The plot index
 */
export function getVisiblePlotEffects(plotIndex: number): PlotTooltipEffectInfo[] {
	const plotEffects = MapPlotEffects.getPlotEffects(plotIndex);
	const localPlayerID: PlayerId = GameContext.localPlayerID;
	const visibleEffects: PlotTooltipEffectInfo[] = [];

	plotEffects?.forEach((item) => {
		const effectInfo = GameInfo.PlotEffects.lookup(item.effectType);
		if (!item.onlyVisibleToOwner || (item.onlyVisibleToOwner && item.owner == localPlayerID)) {
			if (effectInfo) {
				const eventMapping = GameInfo.RandomEventPlotEffects.find(
					(e) => e.PlotEffectType === effectInfo.PlotEffectType,
				);
				const randomEvent = eventMapping
					? GameInfo.RandomEvents.lookup(eventMapping.RandomEventType)
					: undefined;

				visibleEffects.push({
					name: effectInfo.Name,
					plotEffectType: effectInfo.PlotEffectType,
					effectType: item.effectType,
					eventClass: randomEvent?.EventClass,
					eventName: randomEvent?.Name,
					duration: item.duration,
					onlyVisibleToOwner: item.onlyVisibleToOwner,
					owner: item.owner,
				});
			}
		}
	});

	return visibleEffects;
}

/**
 * Get treasure convoy generation info for the city owning a plot.
 * Returns turns remaining if the owning city is actively generating a convoy, otherwise null.
 * @param location The X,Y plot location
 */
export function getTreasureConvoyInfo(owningCity: City | null): { turnsRemaining: number } | null {
	if (!owningCity?.Resources) return null;
	if (!owningCity.Resources.canStartTreasureFleet().Success) return null;
	return { turnsRemaining: owningCity.Resources.getTurnsUntilTreasureGenerated() };
}
